#!/usr/bin/env bash
# block-generated-writes.sh: PreToolUse guard that refuses agent writes to generated files.
#
# Generated files are rewritten by their generator, so a hand edit is lost or
# drifts from the source. Guarded paths, relative to the repository root:
#   - frontend/src/routeTree.gen.ts (TanStack Router plugin)
#   - frontend/src/api/generated/** (Orval)
#   - openapi/openapi.yaml (springdoc through OpenApiContractTest (-PopenapiExport=true))
#   - every path listed in .kiro/.kiro-plugins-installed, and that file itself
#     (cursor-plugins kiro/install.sh)
#
# Contract: read the harness PreToolUse JSON on stdin, print a reason to
# stderr and exit 2 to REFUSE, exit 0 to ALLOW.
# Only write-like tools are judged: the tool name contains write, replace,
# append, delete, edit, create, rename, or relocate, or the tool is code with
# the rename_symbol or format_code operation. Reads always pass.
# Every path field is judged (path, file_path, filePath, targetFile, file,
# sourcePath, destinationPath). The repository root is two levels above this
# script, and Kiro runs hooks there, so a relative path is relative to it.
# Paths outside the repository, such as ~/.kiro or another checkout, pass.
#
# Fail-open: no stdin, invalid JSON, missing jq, or no path field ALLOWS.
#
# ponytail: the generated paths live in this script, and the installed paths
# come from .kiro/.kiro-plugins-installed. `//` and `/./` are collapsed, but
# `..` segments are not resolved. A rename or move tool's edits to other files
# and shell redirections bypass this hook. CI `task fe-route-tree-check`,
# `task api-client-check`, `task be-openapi-check`, and `task skills-check` are the final net.

set -u

payload="$(cat 2>/dev/null || true)"
[ -n "$payload" ] || exit 0
command -v jq >/dev/null 2>&1 || exit 0

root="$(cd "$(dirname "$0")/../.." && pwd)"

# Lowercase with tr, not ${var,,}: macOS ships bash 3.2, where ${var,,} is a
# syntax error and the hook would fail without blocking.
tool_name="$(printf '%s' "$payload" | jq -r '.tool_name // empty' 2>/dev/null | tr '[:upper:]' '[:lower:]' || true)"
case "$tool_name" in
  *write* | *replace* | *append* | *delete* | *edit* | *create* | *rename* | *relocate*) ;;
  code)
    case "$(printf '%s' "$payload" | jq -r '.tool_input.operation // empty' 2>/dev/null || true)" in
      rename_symbol | format_code) ;;
      *) exit 0 ;;
    esac
    ;;
  *) exit 0 ;;
esac

refuse() {
  echo "block-generated-writes: refused. $1" 1>&2
  exit 2
}

# judge <path>: refuse when <path> names a guarded file in this repository.
judge() {
  local path="$1" name
  while [[ "$path" == *//* ]]; do path="${path//\/\//\/}"; done
  while [[ "$path" == */./* ]]; do path="${path//\/.\//\/}"; done
  while [[ "$path" == ./* ]]; do path="${path#./}"; done
  case "$path" in
    "$root"/*) path="${path#"$root"/}" ;;
    /*) return 0 ;;
  esac

  case "$path" in
    frontend/src/routeTree.gen.ts)
      refuse "$1 is generated by the TanStack Router plugin. Edit the files under frontend/src/routes/ instead, then regenerate with \`cd frontend && vp build\` (or keep \`task fe-dev\` running)." ;;
    frontend/src/api/generated/*)
      refuse "$1 is generated by Orval. Change the OpenAPI document or the Orval config instead, then regenerate with \`task api-gen\` (or \`task api-client-gen\` when only the Orval config changed)." ;;
    openapi/openapi.yaml)
      refuse "$1 is generated by springdoc through OpenApiContractTest (-PopenapiExport=true). Change the controllers, DTO Javadoc, or OpenApiConfig, then regenerate with \`task api-gen\`." ;;
    .kiro/.kiro-plugins-installed)
      refuse "$1 is written by cursor-plugins kiro/install.sh. Leave the recorded hashes as they are, and reinstall per docs/agents/skill-sources.md." ;;
  esac

  # Manifest lines are "<path under .kiro/>\t<content hash>" after a "# cursor-plugins <commit>" line.
  [ -f "$root/.kiro/.kiro-plugins-installed" ] || return 0
  while IFS=$'\t' read -r name _; do
    case "$name" in '' | '#'*) continue ;; esac
    case "$path" in
      .kiro/"$name" | .kiro/"$name"/*)
        refuse "$1 was installed by cursor-plugins kiro/install.sh (.kiro/.kiro-plugins-installed). Change it in cursor-plugins kiro/ or upstream, then reinstall per docs/agents/skill-sources.md." ;;
    esac
  done <"$root/.kiro/.kiro-plugins-installed"
}

paths="$(printf '%s' "$payload" | jq -r '.tool_input | (.path, .file_path, .filePath, .targetFile, .file, .sourcePath, .destinationPath) | strings' 2>/dev/null || true)"
while IFS= read -r path; do
  [ -n "$path" ] && judge "$path"
done <<<"$paths"

exit 0
